import jwt from 'jsonwebtoken';

app.get('/auth/google/callback', async (req, res, next) => {
  try {
    const { code } = req.query; // the temporary authorization code

    // STEP 4 - server-to-server exchange, using the client secret,
    // NEVER exposed to the browser at any point
    const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        code: code as string,
        client_id: process.env.GOOGLE_CLIENT_ID!,
        client_secret: process.env.GOOGLE_CLIENT_SECRET!, // genuinely
          // private - read from env, exactly Module 10 lesson 6's rule
        redirect_uri: process.env.GOOGLE_REDIRECT_URI!,
        grant_type: 'authorization_code'
      })
    });

    const { access_token } = await tokenResponse.json();

    // STEP 5a - fetch the user's basic Google profile
    const profileResponse = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', {
      headers: { Authorization: `Bearer ${access_token}` }
    });
    const profile = await profileResponse.json();

    // STEP 5b - find or create a corresponding user in YOUR database
    let user = await usersCollection.findOne({ googleId: profile.id });
    if (!user) {
      const result = await usersCollection.insertOne({
        googleId: profile.id,
        email: profile.email,
        name: profile.name
      });
      user = { _id: result.insertedId, email: profile.email, name: profile.name };
    }

    // STEP 5c - issue YOUR OWN JWT, exactly Module 9's existing mechanism
    const appToken = jwt.sign(
      { userId: user._id.toString(), email: user.email },
      process.env.JWT_SECRET!,
      { expiresIn: '1h' }
    );

    res.redirect(`${process.env.FRONTEND_URL}/auth/callback?token=${appToken}`);
  } catch (err) {
    next(err);
  }
});

