Issuing both tokens at login, directly extending Module 9's existing login route:

function issueTokens(userId: string) {
  const accessToken = jwt.sign({ userId }, process.env.JWT_SECRET!, { expiresIn: '15m' });
  const refreshToken = jwt.sign({ userId }, process.env.REFRESH_SECRET!, { expiresIn: '7d' });
  return { accessToken, refreshToken };
}

app.post('/login', async (req, res, next) => {
  // ... Module 9's existing credential verification ...
  const { accessToken, refreshToken } = issueTokens(user._id.toString());
  await refreshTokensCollection.insertOne({ userId: user._id, refreshToken, revoked: false });
  res.json({ success: true, data: { accessToken, refreshToken } });
});

Using the refresh token to obtain a new access token once the old one expires:

app.post('/refresh', async (req, res, next) => {
  try {
    const { refreshToken } = req.body;
    const stored = await refreshTokensCollection.findOne({ refreshToken, revoked: false });
    if (!stored) {
      return res.status(401).json({ success: false, error: 'Invalid refresh token' });
    }

    const decoded = jwt.verify(refreshToken, process.env.REFRESH_SECRET!) as { userId: string };

    // ROTATION - the old refresh token is revoked and a genuinely NEW
    // one is issued, rather than reusing the same refresh token indefinitely
    await refreshTokensCollection.updateOne({ refreshToken }, { $set: { revoked: true } });
    const tokens = issueTokens(decoded.userId);
    await refreshTokensCollection.insertOne({ userId: decoded.userId, refreshToken: tokens.refreshToken, revoked: false });

    res.json({ success: true, data: tokens });
  } catch (err) {
    res.status(401).json({ success: false, error: 'Invalid or expired refresh token' });
  }
});

