let accessToken: string | null = null;
let refreshToken: string | null = null;

async function apiRequest(url: string, options: RequestInit = {}) {
  const response = await fetch(url, {
    ...options,
    headers: { ...options.headers, Authorization: `Bearer ${accessToken}` }
  });

  if (response.status === 401) {
    // Access token likely expired - attempt a transparent refresh
    // BEFORE giving up and forcing the user to log in again
    const refreshResponse = await fetch('/refresh', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken })
    });

    if (!refreshResponse.ok) {
      // The refresh token itself is invalid/expired too - NOW the user
      // genuinely must log in again, exactly Module 9 lesson 9's pattern
      accessToken = null;
      refreshToken = null;
      throw new Error('Session expired - please log in again');
    }

    const { data } = await refreshResponse.json();
    accessToken = data.accessToken;
    refreshToken = data.refreshToken; // the NEW, rotated refresh token

    // Retry the ORIGINAL request, now with the fresh access token
    return fetch(url, {
      ...options,
      headers: { ...options.headers, Authorization: `Bearer ${accessToken}` }
    });
  }

  return response;
}

