Defining roles as collections of specific permissions:

const ROLE_PERMISSIONS: Record<string, string[]> = {
  viewer: ['posts:read'],
  editor: ['posts:read', 'posts:create', 'posts:update'],
  admin: ['posts:read', 'posts:create', 'posts:update', 'posts:delete', 'users:manage']
};

function hasPermission(userRole: string, permission: string): boolean {
  return ROLE_PERMISSIONS[userRole]?.includes(permission) ?? false;
}

A middleware checking for a SPECIFIC permission, rather than Module 9's hardcoded role string:

function requirePermission(permission: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!hasPermission(req.userRole, permission)) {
      return res.status(403).json({ success: false, error: 'Insufficient permissions' });
    }
    next();
  };
}

app.delete('/posts/:id', requireAuth, requirePermission('posts:delete'), deletePost);
app.post('/users/:id/promote', requireAuth, requirePermission('users:manage'), promoteUser);

