const ROLE_PERMISSIONS: Record<string, string[]> = {
  viewer: ['posts:read'],
  editor: ['posts:read', 'posts:create', 'posts:update'],
  moderator: ['posts:read', 'posts:update', 'comments:delete'],
  admin: ['posts:read', 'posts:create', 'posts:update', 'posts:delete', 'users:manage', 'comments:delete']
};

// A user can hold MULTIPLE roles - permissions are the UNION of all
// their roles' individual permission sets
function getUserPermissions(roles: string[]): Set<string> {
  const permissions = new Set<string>();
  for (const role of roles) {
    for (const permission of ROLE_PERMISSIONS[role] ?? []) {
      permissions.add(permission);
    }
  }
  return permissions;
}

function requirePermission(permission: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    const userPermissions = getUserPermissions(req.userRoles); // array,
                                                                  // not a
                                                                  // single role
    if (!userPermissions.has(permission)) {
      return res.status(403).json({ success: false, error: 'Insufficient permissions' });
    }
    next();
  };
}

// A user who is BOTH an editor AND a moderator correctly gains access
// to comments:delete (from moderator) WHILE retaining posts:create
// (from editor) - the union of both roles' permissions, automatically
app.delete('/comments/:id', requireAuth, requirePermission('comments:delete'), deleteComment);

// Later, granting editors comments:delete too requires ONLY this one
// line changing - zero route or middleware code needs to change at all
// editor: ['posts:read', 'posts:create', 'posts:update', 'comments:delete']

