After installing a TOTP library (otplib, or similar), generating a secret and enrolling a user in MFA:

import { authenticator } from 'otplib';

app.post('/mfa/setup', requireAuth, async (req, res, next) => {
  try {
    const secret = authenticator.generateSecret();
    await usersCollection.updateOne(
      { _id: new ObjectId(req.userId) },
      { $set: { mfaSecret: secret, mfaEnabled: false } } // not yet
        // enabled until the user confirms they've genuinely set it up
    );

    const qrCodeUrl = authenticator.keyuri(req.userEmail, 'MyApp', secret);
    res.json({ success: true, data: { qrCodeUrl, secret } });
  } catch (err) {
    next(err);
  }
});

Verifying a code and finalizing MFA enrollment:

app.post('/mfa/verify-setup', requireAuth, async (req, res, next) => {
  const { code } = req.body;
  const user = await usersCollection.findOne({ _id: new ObjectId(req.userId) });

  const isValid = authenticator.verify({ token: code, secret: user.mfaSecret });
  if (!isValid) {
    return res.status(400).json({ success: false, error: 'Invalid code' });
  }

  await usersCollection.updateOne({ _id: new ObjectId(req.userId) }, { $set: { mfaEnabled: true } });
  res.json({ success: true });
});

