import bcrypt from 'bcrypt';
import { authenticator } from 'otplib';
import jwt from 'jsonwebtoken';

app.post('/login', async (req, res, next) => {
  try {
    const { email, password, mfaCode } = req.body;

    // STAGE 1 - password verification, exactly Module 9's existing logic
    const user = await usersCollection.findOne({ email });
    if (!user) {
      return res.status(401).json({ success: false, error: 'Invalid credentials' });
    }

    const passwordValid = await bcrypt.compare(password, user.password);
    if (!passwordValid) {
      return res.status(401).json({ success: false, error: 'Invalid credentials' });
    }

    // STAGE 2 - a GENUINELY SEPARATE check, only reached if stage 1
    // already succeeded completely
    if (user.mfaEnabled) {
      if (!mfaCode) {
        // password was correct, but MFA is required and no code was
        // provided yet - tell the client specifically to prompt for one
        return res.status(401).json({ success: false, error: 'MFA code required', mfaRequired: true });
      }

      const mfaValid = authenticator.verify({ token: mfaCode, secret: user.mfaSecret });
      if (!mfaValid) {
        return res.status(401).json({ success: false, error: 'Invalid MFA code' });
      }
    }

    // Both stages passed (or MFA wasn't enabled for this user at all)
    const token = jwt.sign({ userId: user._id.toString() }, process.env.JWT_SECRET!, { expiresIn: '1h' });
    res.json({ success: true, data: { token } });
  } catch (err) {
    next(err);
  }
});

