import express from 'express';
import session from 'express-session';
import helmet from 'helmet';
import csrf from 'csurf';

const app = express();

// Security headers - applied broadly, early, to every response
app.use(helmet());

// Secure session cookies
app.use(session({
  secret: process.env.SESSION_SECRET!,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production', // HTTPS-only in
      // production specifically; local development often uses plain HTTP
    sameSite: 'strict',
    maxAge: 60 * 60 * 1000
  }
}));

const csrfProtection = csrf({ cookie: true });

// CSRF protection applied specifically to state-changing routes,
// not blanket-applied to every single route in the application
app.post('/transfer-funds', csrfProtection, requireAuth, transferFundsHandler);
app.post('/change-password', csrfProtection, requireAuth, changePasswordHandler);

// A read-only route genuinely doesn't need CSRF protection at all,
// since CSRF specifically concerns unintended STATE CHANGES, not reads
app.get('/profile', requireAuth, getProfileHandler);

